// Some portions generated by Claude
import test from "node:test";
import assert from "node:assert/strict";
import { GraphScene } from "../../../main/frontend/graph-explorer/graph-scene.ts";
import { computeSparseLayout } from "../../../main/frontend/graph-explorer/graph-layout-sparse.ts";
const fixture = (n) => ({
  nodes: Array.from({ length: n }, (_, i) => ({
    id: `urn:n:${i}`,
    label: `Node ${i}`,
    kind: "iri",
    x: (i % 250) * 260,
    y: Math.floor(i / 250) * 90,
  })),
  edges: Array.from({ length: n }, (_, i) => ({
    id: `e${i}`,
    source: `urn:n:${i}`,
    target: `urn:n:${(i + 1) % n}`,
    predicate: "urn:related",
    label: "related to",
  })),
  revision: 1,
});
test("50,000 vertices have indexed topology and movable spatial hit targets", () => {
  const graph = fixture(50000),
    scene = new GraphScene(graph),
    edges = scene.edges;
  scene.move(302, -1000, -1000);
  assert.equal(scene.pick(-1000, -1000, 10), 302);
  assert.equal(scene.pick(graph.nodes[302].x, graph.nodes[302].y, 10), -1);
  assert.equal(scene.edges, edges);
  assert.deepEqual([...scene.neighbors(302)], [301, 303]);
  assert.equal(scene.positions.byteLength, 400000);
  assert.equal(scene.edges.length, 100000);
});
test("sparse layout handles 50,000 cyclic nodes with bounded storage and no duplicate centers", () => {
  const graph = fixture(50000);
  graph.nodes[0].pinned = true;
  const result = computeSparseLayout(graph);
  assert.equal(result.positions.size, 50000);
  assert.deepEqual(result.positions.get("urn:n:0"), { x: 0, y: 0 });
  const cells = new Set(
    [...result.positions.values()].map((p) => `${p.x},${p.y}`),
  );
  assert.equal(cells.size, 50000);
});
test("incremental sparse layout separates inserted nodes from occupied cells and preserves fixed nodes", () => {
  const graph = fixture(4);
  graph.nodes[3].x = 0;
  graph.nodes[3].y = 0;
  const result = computeSparseLayout(graph, {
    incremental: true,
    movableNodeIds: new Set(["urn:n:3"]),
  });
  assert.notDeepEqual(
    result.positions.get("urn:n:3"),
    result.positions.get("urn:n:0"),
  );
  assert.deepEqual(result.positions.get("urn:n:1"), { x: 260, y: 0 });
});
test("indexed GPU drawing updates eight bytes for a moved node and retains edge indices", async () => {
  const { IndexedGraphGl } = await import("../../../main/frontend/graph-explorer/graph-indexed-gl.ts");
  const calls = [];
  let id = 0;
  const gl = new Proxy(
    {
      canvas: { width: 1280, height: 780 },
      ARRAY_BUFFER: 1,
      ELEMENT_ARRAY_BUFFER: 2,
      UNSIGNED_SHORT: 3,
      UNSIGNED_INT: 4,
      LINES: 5,
      POINTS: 6,
      COMPILE_STATUS: 7,
      LINK_STATUS: 8,
      getExtension: () => ({}),
      getShaderParameter: () => true,
      getProgramParameter: () => true,
      getAttribLocation: () => 0,
      bufferData: (target, data) =>
        calls.push(["data", target, data.byteLength]),
      bufferSubData: (target, offset, data) =>
        calls.push(["sub", target, offset, data.byteLength]),
      drawElements: (mode, count, type) =>
        calls.push(["elements", mode, count, type]),
    },
    {
      get(target, key) {
        if (key in target) return target[key];
        if (String(key).startsWith("create")) return () => ({ id: ++id });
        return () => {};
      },
    },
  );
  const renderer = new IndexedGraphGl(gl),
    scene = new GraphScene(fixture(50000));
  renderer.upload(scene);
  const before = renderer.stats.uploadedBytes;
  calls.length = 0;
  scene.move(42, 150, 300);
  renderer.move(42, scene.positions);
  renderer.draw({ x: 0, y: 0, k: 1 }, 1280, 780, 1);
  assert.equal(renderer.stats.uploadedBytes - before, 8);
  assert.deepEqual(calls[0], ["sub", 1, 336, 8]);
  assert.equal(
    calls.some((call) => call[0] === "data"),
    false,
  );
  assert.deepEqual(calls[1], ["elements", 5, 100000, 3]);
  renderer.dispose();
});
